old="""              <td><app-person-plans [personId]="p.id" [personName]="p.name" /></td>"""
new="""              <td>
                <ul class="holds">
                  @for (line of timeline(p); track $index) {
                    <li data-testid="person-timeline-line">{{ line }}</li>
                  }
                </ul>
              </td>
"""+old
assert old in s
s=s.replace(old,new,1)
old="""  /** The sort keys the list can be shown in. */"""
new="""  /** A person's timeline: one line per dated thing about them, by date, and on a date their grade
   *  changes, then claims (by amount), then holds, then retirements, then unretirements. */
  protected timeline(p: Person): string[] {
    const entries: { date: string; kind: number; amount: bigint; line: string }[] = [];
    const add = (date: string | null, kind: number, line: string, amount = 0n) => {
      if (date !== null) entries.push({ date, kind, amount, line: `${date} ${line}` });
    };
    for (const g of p.grades) add(g.from, 0, `grade ${g.grade}`);
    for (const c of this.claims.of(p.id)) add(c.date, 1, `claim ${c.amount} ${c.status}`, hundredths(c.amount));
    for (const h of p.holds) add(h.from, 2, h.to === null ? 'hold' : `hold to ${h.to}`);
    for (const r of p.retirements) add(r.from, 3, 'retired');
    add(p.retiredFrom, 3, 'retired');
    for (const r of p.retirements) add(r.to, 4, 'unretired');
    return entries
      .sort((a, b) => compareKeys(a.date, b.date) || a.kind - b.kind || (a.amount < b.amount ? -1 : a.amount > b.amount ? 1 : 0))
      .map((e) => e.line);
  }
"""+old
s=s.replace(old,new,1)
open(p,'w').write(s)
